"use client";

import * as React from "react";
import { motion, AnimatePresence, useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";

export type ImageTrailImage = {
  src: string;
  alt?: string;
};

export type ImageTrailProps = {
  /** Images cycled through as the trail. */
  images: ImageTrailImage[];
  /** Minimum cursor travel distance (px) before spawning the next image. */
  spacing?: number;
  /** How long (ms) each image stays visible before fading out. */
  duration?: number;
  /** Width & height of each trail image (px). */
  imageSize?: number;
  /** Border radius of each image (px). */
  cornerRadius?: number;
  /** Fade-in duration (seconds). */
  fadeInDuration?: number;
  /** Fade-out duration (seconds). */
  fadeOutDuration?: number;
  /** Blur applied on entry (px). */
  fadeInBlur?: number;
  /** Blur applied on exit (px). */
  fadeOutBlur?: number;
  /** Lerp factor (0–1) for smoothness — lower = silkier. */
  smoothness?: number;
  /** Enable magnetic repulsion of trail images toward the cursor. */
  magneticEffect?: boolean;
  /** Max distance (px) at which magnetic force kicks in. */
  magneticRadius?: number;
  /** Strength multiplier of the magnetic force (0–1). */
  magneticStrength?: number;
  /** className applied to the root container. */
  className?: string;
  /** Foreground content rendered above the trail layer. */
  children?: React.ReactNode;
};

type TrailEntry = {
  id: number;
  x: number;
  y: number;
  timestamp: number;
  imageIndex: number;
};

let _id = 0;

export function ImageTrail({
  images,
  spacing = 40,
  duration = 1000,
  imageSize = 120,
  cornerRadius = 8,
  fadeInDuration = 0.3,
  fadeOutDuration = 0.5,
  fadeInBlur = 0,
  fadeOutBlur = 6,
  smoothness = 0.7,
  magneticEffect = false,
  magneticRadius = 100,
  magneticStrength = 0.3,
  className,
  children,
}: ImageTrailProps) {
  const reduceMotion = useReducedMotion() === true;
  const containerRef = React.useRef<HTMLDivElement>(null);
  const lastPos = React.useRef({ x: 0, y: 0 });
  const imageIndexRef = React.useRef(0);
  const [trail, setTrail] = React.useState<TrailEntry[]>([]);
  const [mouse, setMouse] = React.useState({ x: 0, y: 0 });

  // Spawn a new trail entry if cursor moved far enough
  const spawn = React.useCallback(
    (x: number, y: number) => {
      if (!images.length) return;
      const dx = x - lastPos.current.x;
      const dy = y - lastPos.current.y;
      if (Math.sqrt(dx * dx + dy * dy) < spacing) return;
      lastPos.current = { x, y };
      const entry: TrailEntry = {
        id: _id++,
        x,
        y,
        timestamp: Date.now(),
        imageIndex: imageIndexRef.current % images.length,
      };
      imageIndexRef.current++;
      setTrail((prev) => [entry, ...prev]);
    },
    [spacing, images.length],
  );

  // Mouse / touch handlers
  const onMouseMove = React.useCallback(
    (e: MouseEvent) => {
      if (!containerRef.current) return;
      const r = containerRef.current.getBoundingClientRect();
      const x = e.clientX - r.left;
      const y = e.clientY - r.top;
      setMouse({ x, y });
      spawn(x, y);
    },
    [spawn],
  );

  const onTouchMove = React.useCallback(
    (e: TouchEvent) => {
      if (!containerRef.current) return;
      e.preventDefault();
      const r = containerRef.current.getBoundingClientRect();
      const t = e.touches[0];
      spawn(t.clientX - r.left, t.clientY - r.top);
    },
    [spawn],
  );

  React.useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    el.addEventListener("mousemove", onMouseMove);
    el.addEventListener("touchmove", onTouchMove, { passive: false });
    return () => {
      el.removeEventListener("mousemove", onMouseMove);
      el.removeEventListener("touchmove", onTouchMove);
    };
  }, [onMouseMove, onTouchMove]);

  // Prune expired entries
  React.useEffect(() => {
    const id = setInterval(() => {
      const now = Date.now();
      setTrail((prev) => prev.filter((e) => now - e.timestamp < duration));
    }, 50);
    return () => clearInterval(id);
  }, [duration]);

  // Preload images
  React.useEffect(() => {
    images.forEach(({ src }) => {
      const img = new Image();
      img.src = src;
    });
  }, [images]);

  const magneticOffset = React.useCallback(
    (ix: number, iy: number) => {
      if (!magneticEffect) return { x: 0, y: 0 };
      const dx = mouse.x - ix;
      const dy = mouse.y - iy;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist > magneticRadius) return { x: 0, y: 0 };
      const force = (magneticRadius - dist) / magneticRadius;
      return { x: dx * force * magneticStrength, y: dy * force * magneticStrength };
    },
    [magneticEffect, mouse, magneticRadius, magneticStrength],
  );

  return (
    <div
      ref={containerRef}
      className={cn(
        "relative overflow-hidden",
        "cursor-none",
        // GPU-layer hint
        "transform-[translateZ(0)] backface-hidden",
        className,
      )}
    >
      {children && <div className="relative z-10">{children}</div>}
      <AnimatePresence mode="popLayout">
        {trail.map((entry, idx) => {
          const img = images[entry.imageIndex];
          if (!img) return null;
          const mag = magneticOffset(entry.x, entry.y);
          return (
            <motion.div
              key={entry.id}
              initial={
                reduceMotion
                  ? { opacity: 0.7 }
                  : { opacity: 1, scale: 0.8, filter: `blur(${fadeInBlur}px)` }
              }
              animate={
                reduceMotion
                  ? { opacity: 0.7 }
                  : {
                      opacity: 1,
                      scale: 1,
                      filter: "blur(0px)",
                      x: mag.x,
                      y: mag.y,
                    }
              }
              exit={
                reduceMotion
                  ? { opacity: 0 }
                  : { opacity: 0, scale: 0.5, filter: `blur(${fadeOutBlur}px)` }
              }
              transition={
                reduceMotion
                  ? { duration: 0.15 }
                  : {
                      duration: smoothness * fadeInDuration * 0.8,
                      ease: "easeOut" as const,
                      x: { duration: 0.1, ease: "easeOut" as const },
                      y: { duration: 0.1, ease: "easeOut" as const },
                    }
              }
              style={{
                position: "absolute",
                left: entry.x - imageSize / 2,
                top: entry.y - imageSize / 2,
                width: imageSize,
                height: imageSize,
                pointerEvents: "none",
                zIndex: trail.length - idx,
                willChange: "transform, opacity, filter",
              }}
            >
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={img.src}
                alt={img.alt ?? ""}
                loading="lazy"
                decoding="async"
                style={{
                  width: "100%",
                  height: "100%",
                  objectFit: "cover",
                  borderRadius: cornerRadius,
                  display: "block",
                }}
              />
            </motion.div>
          );
        })}
      </AnimatePresence>
    </div>
  );
}
